  final candidate = separateParenGroups;

  expect(candidate("(()()) ((())) () ((())()())"), ["(()())", "((()))", "()", "((())()())"]);
  expect(candidate("() (()) ((())) (((())))"), ["()", "(())", "((()))", "(((())))"]);
  expect(candidate("(()(())((())))"), ["(()(())((())))"]);
  expect(candidate("( ) (( )) (( )( ))"), ["()", "(())", "(()())"]);
}

