List<String> separateParenGroups(String parenString) {
  List<String> result = [];
  String currentGroup = "";

  for (int i = 0; i < parenString.length; i++) {
    if (parenString[i] == '(') {
      currentGroup += parenString[i];
    } else if (parenString[i] == ')') {
      currentGroup += parenString[i];

      // Check if we have a complete group
      int balance = 0;
      bool isValid = true;
      for (int j = 0; j < currentGroup.length; j++) {
        if (currentGroup[j] == '(') balance++;
        else balance--;

        if (balance < 0 || balance > currentGroup.length / 2) {
          isValid = false;
          break;
        }
      }

      if (balance == 0 && isValid) {
        result.add(currentGroup);
        currentGroup = "";
      }
    }
  }

  return result;
}

