List<String> separateParenGroups(String parenString) {
  List<String> result = [];

  int openCount = 0;
  String currentGroup = '';

  for (int i = 0; i < parenString.length; i++) {
    if (parenString[i] == '(') {
      openCount++;
      currentGroup += parenString[i];
    } else if (parenString[i] == ')') {
      currentGroup += parenString[i];

      if (openCount <= 0) {
        // Mismatched parentheses - invalid group, skip to next character
        continue;
      }

      openCount--;

      if (openCount == 0 && currentGroup.isNotEmpty) {
        result.add(currentGroup);
        currentGroup = '';
      }
    }

    // Skip unmatched closing parentheses
    if (currentGroup.isEmpty && parenString[i] == ')' && openCount > 0) {
      continue;
    }
  }

  return result;
}

tests:
void main() {
  final candidate = separateParenGroups;

  expect(candidate("(()()) ((())) () ((())()())"), ["(()())", "((()))", "()", "((())()())"]);
  expect(candidate("() (()) ((())) (((())))"), ["()", "(())", "((()))", "(((())))"]);
  expect(candidate("(()(())((())))"), ["(()(())((())))"]);
  expect(candidate("( ) (( )) (( )( ))"), ["()", "(())", "(()())"]);
}

