dart_source:
int countDistinctCharacters(String string) {
  if (string.length == 0) return 0;

  int distinct = 1;

  for (int i = 1; i < string.length; i++) {
    String currentCharacter = string[i];

    bool foundMatch = false;
    for (int j = 0; !foundMatch && j <= i - 1; j++) {
      if (currentCharacter.toLowerCase() == string[j].toLowerCase()) {
        foundMatch = true;
      } 
    } 

    if (!foundMatch) {
      distinct++;
    }
  } 

  return distinct;
}

