String sortNumbers(String numbers) {
  if (numbers.isEmpty || numbers.trim().isEmpty) return '';

  List<String> tokens = [];
  for (int i = 0; i < numbers.length - 1; i++) {
    String word = '';
    while (i < numbers.length && !RegExp(r'\s').hasMatch(numbers[i])) {
      word += numbers[i];
      i++;
    }
    tokens.add(word);
  }

  Map<int, Set<String>> numToWords = {};
  const wordsMap = {
    'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
    'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'zero': 0
  };

  for (var token in tokens) {
    var numberValue = wordsMap[token.toLowerCase()];
    if (numberValue != null) {
      numToWords.putIfAbsent(numberValue, () => {}).add(token);
    } else {
      // Keep non-numeric words at the end
      print('Non numeric: $token'); 
    }
  }

  List<MapEntry<int, Set<String>>> sortedEntries =
      numToWords.entries.toList(growable: false)..sort((a, b) => a.key.compareTo(b.key));

  final resultParts = sortedEntries.map((entry) => entry.value.join(" ")).toList();
  String resultText = resultParts.join(" ");

  return resultText;
}

