int primeFib(int n) {
  if (n == 1) return 2; 
  else if (n == 2) return 3; 


  List<int> fib = [0, 1];
  int a = 2, b = 3;

  while (fib.length < n) {
    int next = a + b;
    bool isPrime = true;
    for (int i = 2; i * i <= next; i++) {
      if (next % i == 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime) fib.add(next);
    a = b;
    b = next;
  }

  return fib[n - 1]; 
}

