  List<double> sortedList = [...l].map((e) => e.toDouble()).toList();
  sortedList.sort((a, b) => a.compareTo(b));

  int n = sortedList.length;
  if (n % 2 == 0) {
    double mid1 = sortedList[n ~/ 2 - 1];
    double mid2 = sortedList[n ~/ 2];
    return (mid1 + mid2) / 2.0;
  } else {
    return sortedList[n ~/ 2];
  }
}

