double median(List<num> l) {
  if (l.isEmpty) return 0; // Handle empty list

  List<num> sortedList = [...l]..sort(); // Copy and sort the input list

  int middleIndex = sortedList.length ~/ 2; // Calculate the index of the middle element(s)

  if (sortedList.length % 2 == 1) { // Odd number of elements, single median value
    num medianValue = sortedList[middleIndex];
    print('The odd count median is $medianValue');
    return double.parse(medianValue.toString());
  } else { 
    // Even number of elements, average the two middle values for median
    num lowerMiddleValue = sortedList[middleIndex - 1].toDouble();
    num upperMiddleValue = sortedList[middleIndex].toDouble();
    num sumOfTwoValues = lowerMiddleValue + upperMiddleValue; // Sum the two middle numbers
    double medianValue = sumOfTwoValues / 2.0; // Divide by 2 to get the average

    print("The even count median is ${sumOfTwoValues}");

    return medianValue;
  }
}

