bool belowThreshold(List<int> l, int t) {
  if (l.length == 0) return false;

  var sum = l.reduce((a,b)=>a+b);
  for(var i=1;i<l.length;++i){
    if(sum<t)return true;
    sum-=l[i-1];
  }
  return sum < t;
}

