bool monotonic(List<num> l) {
  bool ascending = true;
  for (int i = 1; i < l.length; ++i) if (l[i] < l[i - 1]) ascending = false;

  bool descending = true;
  for (int i = 0; i < l.length - 1; ++i) if (l[i + 1] > l[i]) descending = false;

  return ascending || descending;
}

