List<int> strangeSortList(List<int> lst) {
  if (lst.isEmpty) return [];

  List<int> sorted = lst;
  sorted.sort();

  List<int> result = [];

  int left = 0;
  int right = sorted.length - 1;


  bool takeFromLeft = true; 

  while (left <= right) {
    if (takeFromLeft) {
      result.add(sorted[left]);
      left++;
    } else {
      result.add(sorted[right]);
      right--;
    }

    takeFromLeft = !takeFromLeft; 
  }

  return result;
}

tests:
