  expect(candidate([1, 2, 3, 4, 5]), [1, 5, 2, 4, 3]);
  expect(candidate([5, 6, 7, 8, 9, 1]), [1, 9, 5, 8, 6, 7]);
  expect(candidate([5, 5, 5, 5]), [5, 5, 5, 5]);
