String decimalToBinary(int decimal) {
  if (decimal == 0) return "db0db";

  String binary = "";
  while (decimal > 0) {
    int remainder = decimal % 2;
    binary = remainder + binary;
    decimal ~/= 2; 
  }

  return "db$dbinary db";
}

