List<int> countUpTo(int n) {
  final List<int> result = [];

  if (n == 0 || n == 1) return result;

  int num = 2;
  while (num < n) {
    bool isPrime = true;
    for (int i = 2; i * i <= num; i++) {
      if (num % i == 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime) {
      result.add(num);
    }
    num++;
  }

  return result;
}

