List<int> countUpTo(int n) {
  if (n <= 1) return [];

  List<int> primes = [2];

  for (int i = 3; i <= n; i += 2) {
    bool isPrime = true;

    for (var p in primes) {
      if (p * p > i) break;

      if (i % p == 0) {
        isPrime = false;
        break;
      }
    }

    if (isPrime) {
      primes.add(i);
    }
  }

  return primes.where((prime) => prime >= 2 && prime < n).toList();
}

