int minSubArraySum(List<int> nums) {
  int currMin = nums.first; 
  int globalMin = currMin;

  for (var i in nums.skip(1)) {
    currMin = (currMin + i < i) ? currMin + i : i;

    if (currMin < globalMin) {
      globalMin = currMin;
    }
  }

  return globalMin;
}

