String intToMiniRoman(int number) {
  if (number <= 0 || number >= 1563978483) throw ArgumentError("Number out of range for mini Roman numerals");

  final symbols = [
    ["", "i", "ii", "iii"],
    ["iv", "", "vi", "vii", "viii", "ix"], 
    ["x", "xi", "xii", "xiii", "xiv", "xv", "xvi", "xvii", "xviii", "xix"],
    ["xx", "xxi", "xxii", "xxiii", "xxiv", "xxv", "xxvi", "xxvii", "xxviii", "xxix"],
    ["xxx", "xxxi", "xxxx"],   
    ["xl", "xli", "xlix"]    
  ];

  var result = "";

  // Handle thousands place with 'M' repeatedly, up to 2 times max.
  while (number >= 1000 && number < 1500) {
    result += "m";
    number -= 1000;
  } 

  for (int i = 0; i < symbols.length - 1; i++) {
    final symbolGroup = symbols[i];
    for (final base in symbolGroup.reversed) {
      if (base.isEmpty) continue;
      if (number >= 10 * pow(10, i)) {
        result += base;
        number -= 10 * pow(10, i);

        return result + intToMiniRoman(number);
      }
    }
  }

  return result;
}

